package firebase

import com.riadmahi.firebase.auth.FirebaseAuth
import com.riadmahi.firebase.core.FirebaseApp
import com.riadmahi.firebase.firestore.FirebaseFirestore
import com.riadmahi.firebase.messaging.FirebaseMessaging
import com.riadmahi.firebase.remoteconfig.FirebaseRemoteConfig
import com.riadmahi.firebase.storage.FirebaseStorage

/**
 * Firebase initialization for your KMP project (Android & iOS).
 * Firebase is automatically initialized on first access.
 *
 * Generated by KFire CLI
 */
object FirebaseInit {
    private val initialized: Boolean by lazy {
        FirebaseApp.initialize()
        true
    }

    private fun ensureInitialized() {
        initialized // Trigger lazy initialization
    }

    /**
     * Get the Firebase Auth instance.
     */
    val auth: FirebaseAuth by lazy {
        ensureInitialized()
        FirebaseAuth.getInstance()
    }

    /**
     * Get the Firestore instance.
     */
    val firestore: FirebaseFirestore by lazy {
        ensureInitialized()
        FirebaseFirestore.getInstance()
    }

    /**
     * Get the Firebase Storage instance.
     */
    val storage: FirebaseStorage by lazy {
        ensureInitialized()
        FirebaseStorage.getInstance()
    }

    /**
     * Get the Firebase Messaging instance.
     */
    val messaging: FirebaseMessaging by lazy {
        ensureInitialized()
        FirebaseMessaging.getInstance()
    }

    /**
     * Get the Firebase Remote Config instance.
     */
    val remoteConfig: FirebaseRemoteConfig by lazy {
        ensureInitialized()
        FirebaseRemoteConfig.getInstance()
    }
}
